/**
 * Hand-rolled Supabase Database types.
 *
 * Normally generated by `supabase gen types typescript`, but the Supabase CLI
 * isn't connected to a live project yet. Worker A's migrations are the source
 * of truth for the shape here. Once the schema is applied to a real project,
 * run `npm run gen:db-types` (added in Phase 3) to regenerate this file —
 * the content below will be overwritten.
 *
 * In the meantime, these types are complete enough for Workers B and C to
 * build against safely.
 */

export type Json =
  | string
  | number
  | boolean
  | null
  | { [key: string]: Json | undefined }
  | Json[];

export type BookingStatus =
  | "pending_payment"
  | "confirmed"
  | "cancelled"
  | "refunded"
  | "expired";

export type EventStatus = "draft" | "published" | "closed" | "cancelled";
export type TimeWindow = "morning" | "midday" | "afternoon" | "any";
export type Attendance = "stay" | "drop";
export type AdminRole = "owner" | "editor" | "viewer";
export type EmailTemplate =
  | "confirmation"
  | "reminder_48h"
  | "day_of"
  | "thank_you"
  | "waitlist_opened"
  | "receipt";

